          </div>
          <LiveRegion message={message} />
        </SettleItem>
      </Reveal>
    </section>
  );
}

function announcementOf(isCopied: boolean, joined: number) {
  if (isCopied) {
    return 'Invite link copied';
  }
  return `${joined} of ${MEMBER_TOTAL} have joined`;
